#!/usr/bin/env python3
import pathlib
import sys

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent / "lib"))
from kaya_gate import Gate, dev_shell_or_die

dev_shell_or_die()

# crates/kaya/src/winui/bindings.rs is GENERATED by tools/winui-bindgen from
# the Windows App SDK metadata in third_party/, and nothing held the two
# together: a filter line added to the generator and never regenerated was
# invisible to every gate (docs/traps.md 2026-09-11, found while the WinUI
# rich text arm needed four vtable slots that were dead pads). The
# generator's own `--check` regenerates into a scratch file and compares;
# this gate runs it, and runs it once more against a doctored copy so the
# refusal is watched red on every run.

import shutil
import subprocess
import tempfile

ROOT = pathlib.Path(__file__).resolve().parent.parent
GEN = ROOT / "tools/winui-bindgen"
BINDINGS = ROOT / "crates/kaya/src/winui/bindings.rs"

gate = Gate("check-winui-bindings")


def run_check(against):
    got = subprocess.run(
        ["cargo", "run", "--locked", "--quiet", "--", "--check", "--against", str(against)],
        cwd=GEN, capture_output=True, text=True, encoding="utf-8", errors="replace",
        check=False)
    return got.returncode, (got.stdout + got.stderr)


rc, text = run_check(BINDINGS)
if rc == 2:
    gate.refuse("the Windows App SDK metadata is not fetched (tools/fetch-winappsdk.sh), "
                "so the bindings cannot be regenerated to compare: " + text.strip())
if rc != 0:
    print(text.strip(), file=sys.stderr)
    print("check-winui-bindings: FAIL")
    raise SystemExit(1)
print(text.strip())

# THE WATCHED NEGATIVE: one byte moved in a COPY must be refused by name.
with tempfile.TemporaryDirectory() as tmp:
    copy = pathlib.Path(tmp) / "bindings.rs"
    shutil.copyfile(BINDINGS, copy)
    raw = copy.read_bytes()
    at = raw.find(b"pub struct ")
    if at < 0:
        gate.refuse("no `pub struct` in bindings.rs to perturb")
    doctored = raw[:at] + b"pub strukt " + raw[at + len(b"pub struct "):]
    print(f"check-winui-bindings: negative perturbed 1 byte sequence at offset {at}")
    copy.write_bytes(doctored)
    n_rc, n_text = run_check(copy)
    gate.negative("a bindings file one word away from the generator's output",
                  lambda: [n_text] if n_rc == 1 else [], want="is STALE against")
gate.negatives_ran(1)
gate.verdict()
